@page "/apply"
@using sv_88e4c1d9437d40b5b9cecbc63499d717.Services
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

@* Step Indicator Bar *@
<div class="step-indicator">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var stepIndex = i;
        var stepClass = GetStepClass(stepIndex);
        <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
            <div class="step-circle">
                @if (stepIndex < CurrentStep)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[stepIndex]</div>
        </div>
        @if (i < StepNames.Length - 1)
        {
            <div class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></div>
        }
    }
</div>

@if (!string.IsNullOrEmpty(_errorMessage))
{
    <div class="alert alert-danger mt-3">@_errorMessage</div>
}

@* Step Content *@
<div class="step-content mt-4">
    @switch (CurrentStep)
    {
        case 0:
            @* Personal Info *@
            <h3>Personal Information</h3>
            <div class="mb-3">
                <label class="form-label">Full Name *</label>
                <input type="text" class="form-control" @bind="_fullName" />
            </div>
            <div class="mb-3">
                <label class="form-label">Email *</label>
                <input type="email" class="form-control" @bind="_email" />
            </div>
            <div class="mb-3">
                <label class="form-label">Phone *</label>
                <input type="tel" class="form-control" @bind="_phone" />
            </div>
            <div class="mb-3">
                <label class="form-label">Address *</label>
                <input type="text" class="form-control" @bind="_address" />
            </div>
            <div class="d-flex justify-content-end">
                <button class="btn btn-primary" @onclick="NextStep" disabled="@_isValidating">
                    @(_isValidating ? "Validating..." : "Next")
                </button>
            </div>
            break;

        case 1:
            @* Work History *@
            <h3>Work History</h3>
            @for (int i = 0; i < _workEntries.Count; i++)
            {
                var idx = i;
                <div class="card mb-3 p-3">
                    <div class="d-flex justify-content-between align-items-center mb-2">
                        <h5 class="mb-0">Position @(idx + 1)</h5>
                        @if (_workEntries.Count > 1)
                        {
                            <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(idx)">Remove</button>
                        }
                    </div>
                    <div class="mb-2">
                        <label class="form-label">Company *</label>
                        <input type="text" class="form-control" @bind="_workEntries[idx].Company" />
                    </div>
                    <div class="mb-2">
                        <label class="form-label">Job Title *</label>
                        <input type="text" class="form-control" @bind="_workEntries[idx].Title" />
                    </div>
                    <div class="row mb-2">
                        <div class="col-md-6">
                            <label class="form-label">Start Date *</label>
                            <input type="date" class="form-control" @bind="_workEntries[idx].StartDate" />
                        </div>
                        <div class="col-md-6">
                            <label class="form-label">End Date</label>
                            <input type="date" class="form-control" @bind="_workEntries[idx].EndDate" disabled="@_workEntries[idx].IsCurrent" />
                            <div class="form-check mt-1">
                                <input type="checkbox" class="form-check-input" id="current-@idx" @bind="_workEntries[idx].IsCurrent" />
                                <label class="form-check-label" for="current-@idx">Currently working here</label>
                            </div>
                        </div>
                    </div>
                    <div class="mb-2">
                        <label class="form-label">Description</label>
                        <textarea class="form-control" rows="3" @bind="_workEntries[idx].Description"></textarea>
                    </div>
                </div>
            }
            <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>
            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-primary" @onclick="NextStep">Next</button>
            </div>
            break;

        case 2:
            @* References *@
            <h3>References</h3>
            @for (int i = 0; i < _references.Count; i++)
            {
                var idx = i;
                <div class="card mb-3 p-3">
                    <div class="d-flex justify-content-between align-items-center mb-2">
                        <h5 class="mb-0">Reference @(idx + 1)</h5>
                        @if (_references.Count > 2)
                        {
                            <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(idx)">Remove</button>
                        }
                    </div>
                    <div class="mb-2">
                        <label class="form-label">Name *</label>
